import test from "node:test"
import assert from "node:assert/strict"
import { parseLine } from "../src/csv.mjs"

test("普通行按逗号拆分", () => {
  assert.deepEqual(parseLine("a,b,c"), ["a", "b", "c"])
})

test("引号内逗号不拆分", () => {
  assert.deepEqual(parseLine('a,"b,c",d'), ["a", "b,c", "d"])
})

test("双引号转义", () => {
  assert.deepEqual(parseLine('a,"b""c",d'), ["a", 'b"c', "d"])
})
